mapper.select:
SELECT receipt_json FROM mk_decision_execution_receipt WHERE 
  AND namespace_name=#{namespace} AND activation_sequence=#{sequence} AND deployment_sequence=#{deployment}
  AND instance_id=#{instance}

SELECT EXISTS (SELECT 1 FROM mk_bundle_applied_authorization WHERE 
  AND JSON_UNQUOTE(JSON_EXTRACT(directive_json,'$.bundle.bundleId'))=#{bundleId}
  AND CAST(JSON_EXTRACT(directive_json,'$.bundle.version') AS UNSIGNED)=#{version}
  AND JSON_UNQUOTE(JSON_EXTRACT(directive_json,'$.bundle.contentHash'))=#{hash})
